		MOD (DOCUMENT_ID * TO_NUMBER(to_char(SYSTIMESTAMP,'FF')),
                         1500)
                       rand_order from nyehms_Sasdb_owner.er_person_clusters_Stage where REVIEW_DATE is null and current_process_Status in (17)  and doc_type = #{documentType}  


	        AND MATCH_CD =  #{filterCriteriaForStatusCode} 


	        AND file_name =  #{filterCriteriaForFileName} 


